#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int itemCount;
    int capacity;

    if (!(cin >> itemCount >> capacity)) {
        return 0;
    }

    if (itemCount < 0 || capacity < 0) {
        return 0;
    }

    vector<int> weights(itemCount);
    vector<int> values(itemCount);

    for (int i = 0; i < itemCount; ++i) {
        cin >> weights[i];
    }

    for (int i = 0; i < itemCount; ++i) {
        cin >> values[i];
    }

    vector<int> dp(capacity + 1);

    // 逆序遍历容量避免同一物品被重复选择
    for (int i = 0; i < itemCount; ++i) {
        if (weights[i] <= 0 || values[i] < 0) {
            continue;
        }

        for (int currentCapacity = capacity;
             currentCapacity >= weights[i];
             --currentCapacity) {
            dp[currentCapacity] = max(
                dp[currentCapacity],
                dp[currentCapacity - weights[i]] + values[i]
            );
        }
    }

    cout << dp[capacity] << '\n';

    return 0;
}

